import React from "react";
import MapTracker from "../components/MapTracker";

export default function DeliveryMapView() {
  // Replace with dynamic values from backend
  const deliveryLocation = { lat: 6.9271, lng: 79.8612 };

  return (
    <div>
      <h2>Track Delivery</h2>
      <MapTracker lat={deliveryLocation.lat} lng={deliveryLocation.lng} />
    </div>
  );
}
